"""
    Trim spaces from values of the args dict.

    :param args: Dict to trim spaces from
    :type args: dict
    :return:
    """
def trim_spaces_from_args(args: Any) -> object {
    for (key, val) in args.items() {
        if isinstance(val, str) {
            args[key] = val.strip();
        }
    }
    return args;
}

